window.products.push({"id":1026864,"name":"Next Innovations Pottery Refraxions 3D Wall Art","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41oHNGfi4cL._AC_.jpg","description":"Next Innovations Pottery Refraxions 3D Wall Art. Experience a whole new dimension in light reflective art. RefraXion pieces are laser cut from 18 gauge steel; powder coated for rust resistance and durable enough to be used indoors or outdoors. Each piece is hand crafted with a grind pattern that creates a dimension to the piece that is impossible to capture in photos. This effect combines with the vibrancy of our color Infusion process. All the RefraXion pieces have brackets on the back that allow the product to hang away from the wall and the art is designed with pieces that have parts that can be bent out to give it a total 3D effect. Measures 22.2-inch by 11.5-inch.","images":["https://m.media-amazon.com/images/I/41oHNGfi4cL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Next Innovations","source_asin":"B008RVVDKK","category_path":"Home & Kitchen"},"sku":"BM-1026864","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B008RVVDKK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B008RVVDKK","price_pending":true,"merchant_ready":false});
